 formTabs([['변화','#costDetails'],['얻기·잃기','#fixedGainField','#rewardDetails','#cLoseGroup'],['조건','#cRequiresGroup','#cRequiresExtra','#cRemember','#cRememberInline','#cRememberQuick'],['다음','#cNext','#cNextInline','#editChoiceNext'],['다른 결과','#branchDetails']]);
