 const groups=['cRequires','cGain','cLose','bWhen','bGain','bLose','cAff','bAff'],opened=new Set(),syncFields=[...groups.flatMap(rowIds).map(([id,countId])=>bindItemField(id,countId)),bindItemField('cRemember')];
