function paintArt(target,p,e,k){const slot=C.art(p,e,k),fallback=()=>{target.replaceChildren();if(slot.text){const text=document.createElement('span');text.className='artFallback';text.textContent=slot.text;target.append(text);}};target.replaceChildren();if(slot.image){const img=new Image();img.src=slot.image;img.alt=k==='top'?'위 그림':'아래 그림';img.style.objectFit=slot.fit;img.style.objectPosition='50% '+slot.y+'%';img.onerror=()=>{if(img.parentElement===target)fallback();};target.append(img);}else fallback();}
