function effectForm(d){const base=(d.effects||[]).find(f=>!f.with)||{},combo=(d.effects||[]).find(f=>f.with)||{};const kindOptions=value=>'<option value="">없음</option>'+Object.entries(C.effectKinds).map(([k,v])=>`<option value="${k}" ${k===value?'selected':''}>${v}</option>`).join('');return `<details id="passiveSettings" ${d.effects?.length?'open':''}><summary>보유 효과 · 선택</summary><p class="hint">보유 중인 동안 적용합니다. 수량·레벨에 따라 배수로 늘어나지 않습니다.</p><label>기본 효과<select id="dEffect">${kindOptions(base.kind)}</select></label><label id="dAmountRow" ${base.kind?'':'hidden'}>효과량<input id="dAmount" type="number" min="1" max="99" value="${base.amount||1}"></label><details id="comboSettings" ${combo.with?'open':''}><summary>다른 항목과 조합</summary><p class="hint">두 항목을 모두 보유하면 추가로 적용합니다. 기본 효과와 합산하며 자동 소모하지 않습니다.</p><label>함께 보유할 항목<select id="dPartner"><option value="">없음</option>${project.definitions.filter(x=>x.id!==d.id&&x.type!=='affinity').map(x=>`<option value="${x.id}" ${x.id===combo.with?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><div id="dComboFields" ${combo.with?'':'hidden'}><label>조합 효과<select id="dComboEffect">${kindOptions(combo.kind)}</select></label><label>효과량<input id="dComboAmount" type="number" min="1" max="99" value="${combo.amount||1}"></label></div></details></details>`;}
function readEffects(){const out=[];if($('dEffect').value){const amount=numeric('dAmount',1,99);if(amount===null)return null;out.push({kind:$('dEffect').value,amount});}if($('dPartner').value){const amount=numeric('dComboAmount',1,99),kind=$('dComboEffect').value;if(!kind||amount===null)return null;out.push({kind,amount,with:$('dPartner').value});}return out;}
function rewardForm(c){return `<details id="rewardDetails" ${c.reward?'open':''}><summary>랜덤 보상 · 선택</summary><label><input id="cRewardOn" type="checkbox" ${c.reward?'checked':''}> 후보 중 최대 3개를 뽑아 하나 선택</label><div id="rewardFields" ${c.reward?'':'hidden'}><p class="hint">모든 후보는 같은 확률입니다. 이미 보유한 항목도 나올 수 있으며, 고른 항목만 얻습니다.</p><label>고른 항목의 수량·레벨<input id="cRewardCount" type="number" min="1" max="99" value="${c.reward?.count||1}"></label>${project.definitions.length?'<input id="rewardSearch" placeholder="보상 후보 검색" aria-label="보상 후보 검색">':'<p class="hint">보유 항목을 먼저 등록하세요.</p>'}${project.definitions.filter(d=>d.type!=='affinity').map(d=>`<label class="rewardCandidate" data-reward-name="${esc(d.name.toLocaleLowerCase())}"><input id="reward_${d.id}" data-reward-id="${d.id}" type="checkbox" ${c.reward?.pool.includes(d.id)?'checked':''}> ${esc(d.name)}</label>`).join('')}</div></details>`;}
function readReward(){if(!$('cRewardOn').checked)return undefined;const pool=[...$('modalBody').querySelectorAll('[data-reward-id]:checked')].map(x=>x.dataset.rewardId),count=numeric('cRewardCount',1,99);return !pool.length||count===null?null:{pool,count};}
// Why an item cannot become (or stop being) 호감도 while choices use it, or '' when it can.
function typeClash(id,type){const was=project.definitions.find(d=>d.id===id)?.type;if(!was||(was==='affinity')===(type==='affinity'))return '';const has=(list,x=id)=>list.some(y=>y.id===x);
 for(const e of project.events){for(const c of e.choices)for(const o of [c,c.branch].filter(Boolean)){if(type==='affinity'&&(has(C.gainsOf(o))||has(C.losesOf(o))||c.remember===id||c.reward?.pool.includes(id)))return '획득·소모·기억·랜덤 보상에 쓰여서 호감도로 바꿀 수 없어요. 그 선택지에서 먼저 빼 주세요.';if(type!=='affinity'&&(has(C.affinityOf(o))||[...C.needsOf(c),...C.whensOf(c.branch)].some(x=>x.id===id&&(x.le||x.count<1))))return '선택지의 호감도 변화나 이하·0 이하 조건에 쓰여서 다른 종류로 바꿀 수 없어요.';}if(type!=='affinity'&&C.appearOf(e).some(x=>x.id===id&&(x.le||x.count<1)))return '랜덤 등장 조건(이하·0 이하)에 쓰여서 다른 종류로 바꿀 수 없어요.';}
 if(type==='affinity'&&project.definitions.some(d=>d.effects?.some(f=>f.with===id)))return '다른 항목의 조합 효과에 쓰여서 호감도로 바꿀 수 없어요.';return '';}
function definitionForm(existing){
 const pending=!existing?Object.values(store.formDrafts||{}).find(d=>d.type==='definition'&&d.game===store.active&&!project.definitions.some(x=>x.id===d.id)):null;
 const d=existing||{id:pending?.id||C.uid(),name:'',type:'ability',initial:0};
 open('보유 항목',`<label>이름<input id="dName" maxlength="80" value="${esc(d.name)}"></label><div class="row"><label>종류<select id="dType"><option value="ability">능력</option><option value="item">아이템</option><option value="state">상태</option><option value="memory">기억 · 숨은 표시</option><option value="affinity">호감도 · 인물과의 관계</option></select></label><label><span id="dInitialLabel">시작 수량·레벨</span><input id="dInitial" type="number" min="0" max="99" value="${d.initial}"></label></div><p id="dMemoryHint" class="hint" hidden>기억은 가방·획득 알림에 보이지 않습니다. 지난 선택을 표시해 조건, 선택지 숨김, 대사 변주 {이름? …}에 씁니다.</p><p id="dAffinityHint" class="hint" hidden>호감도는 ${C.AFFINITY[0]}~${C.AFFINITY[1]} 사이에서 오르내리고, 내려도 선택지가 잠기지 않습니다. 선택지 → 변화 탭에서 바꾸고, 조건(이상·이하)과 대사 변주 {이름>=3? …}에 씁니다.</p><label id="dHiddenRow" class="checkLine" hidden><input type="checkbox" id="dHidden" ${d.hidden?'checked':''}> 플레이어에게 숨김 (가방·알림에 안 보임)</label>${effectForm(d)}<input id="image" type="hidden" value="${esc(d.image||'')}"><input id="imageX" type="hidden" value="${C.imageOffset(d.imageX)}"><input id="imageY" type="hidden" value="${C.imageOffset(d.imageY)}"><details id="acquisitionSettings"><summary>획득 연출 · 그림과 강조</summary><p class="hint">여백 없이 채웁니다. 그림을 끌어서 보여줄 부분을 맞추세요. 그림이 없으면 대사를 유지합니다.</p><label><input id="highlightAcquisition" type="checkbox" ${d.highlight?'checked':''}> 특별 획득으로 강조</label><img id="acquisitionPreview" alt="획득 연출 그림 미리보기" tabindex="0" aria-label="그림 위치 조정 · 드래그 또는 방향키, Home 키로 중앙" hidden><div class="row"><button id="pickAcquisitionImage">그림 선택</button><button id="removeAcquisitionImage" class="quiet" hidden>그림 제거</button><button id="centerAcquisitionImage" class="quiet" hidden>중앙</button></div></details><details id="definitionSoundSettings"><summary>획득 효과음</summary>${audioControl('dSound','이 항목의 획득 소리')}<p class="hint">지정하지 않으면 게임 기본 효과음을 사용합니다.</p></details><div class="formFooter"><small id="formSaveStatus">입력은 자동 저장됩니다.</small>${existing?'<button id="deleteDef" class="quiet iconButton danger" aria-label="보유 항목 삭제">✕</button>':''}<button id="saveDef">완료</button></div>`);formTabs([['기본','#dType','#dMemoryHint','#dAffinityHint','#dHiddenRow'],['보유 효과','#passiveSettings'],['획득 그림','#acquisitionSettings'],['효과음','#definitionSoundSettings']]);if($('deleteDef'))$('deleteDef').onclick=()=>{if(!confirm('「'+existing.name+'」'+josa(existing.name,'을')+' 삭제할까요? 관련된 획득·소모·조건도 함께 지웁니다.'))return;activeForm=null;$('modalBody').oninput=$('modalBody').onchange=null;$('modal').close();deleteDefinition(existing.id);renderDefs();tell('보유 항목을 삭제했습니다. ↶ 되돌리기로 복구할 수 있어요.');};$('dType').value=d.type;fillAudioControl('dSound',d.sound,60);
 const commit=explicit=>{const affinity=$('dType').value==='affinity',n=$('dName').value.trim(),v=affinity?numeric('dInitial',...C.AFFINITY):numeric('dInitial',0,99),effects=affinity?[]:readEffects();if(effects===null){if(explicit)formError('효과량과 조합 효과를 확인하세요.');return false;}
 // 호감도 and items live in different lists: a type change may not leave either one where it cannot be.
 const clash=existing&&typeClash(d.id,$('dType').value);if(clash){if(explicit)formError(clash,'dType');$('formSaveStatus').textContent='작성 중 · 입력을 보관합니다.';return false;}
 if(!n||v===null||project.definitions.some(x=>x.id!==d.id&&x.name===n)||reservedName(n)){if(explicit){if(v===null&&n&&!reservedName(n)&&!project.definitions.some(x=>x.id!==d.id&&x.name===n))formError(affinity?'시작 호감도는 '+C.AFFINITY[0]+'~'+C.AFFINITY[1]+' 사이 정수로 입력하세요.':'시작 수량은 0~99 사이 정수로 입력하세요.','dInitial');else formError(reservedName(n)||(n?'같은 이름의 항목이 이미 있습니다.':'이름을 입력하세요.'),'dName');}$('formSaveStatus').textContent='작성 중 · 입력을 보관합니다.';return false;}
 const existingDef=project.definitions.find(x=>x.id===d.id),next={id:d.id,name:n,type:$('dType').value,initial:v},art=affinity?null:C.image($('image').value);if(effects.length)next.effects=effects;if(affinity&&$('dHidden').checked)next.hidden=true;if(art){next.image=art;next.imageX=C.imageOffset(Number($('imageX').value));next.imageY=C.imageOffset(Number($('imageY').value));}if($('highlightAcquisition').checked&&!affinity)next.highlight=true;const sound=affinity?null:readAudioControl('dSound');if(sound)next.sound=sound;if(!existingDef&&project.definitions.length>=300){if(explicit)formError('보유 항목은 최대 300개입니다.');return false;}
 if(existingDef){if(JSON.stringify(existingDef)===JSON.stringify(next))return true;if(existingDef.name!==next.name)SceneHelpers.renameEverywhere(existingDef.name,next.name);Object.assign(existingDef,next);if(!next.effects)delete existingDef.effects;if(!next.sound)delete existingDef.sound;if(!next.highlight)delete existingDef.highlight;if(!next.hidden)delete existingDef.hidden;if(!art)for(const k of ['image','imageX','imageY'])delete existingDef[k];}else project.definitions.push(next);$('formSaveStatus').textContent='자동 저장됨';persist();return true;};
 const refresh=()=>{const memory=$('dType').value==='memory',affinity=$('dType').value==='affinity';$('dMemoryHint').hidden=!memory;$('dAffinityHint').hidden=$('dHiddenRow').hidden=!affinity;$('dInitialLabel').textContent=affinity?'시작 호감도':'시작 수량·레벨';$('dInitial').min=affinity?C.AFFINITY[0]:0;$('dInitial').max=affinity?C.AFFINITY[1]:99;for(const id of ['passiveSettings','acquisitionSettings','definitionSoundSettings'])$(id).hidden=memory||affinity;$('modalBody').querySelectorAll('[data-form-tab]').forEach((b,i)=>b.hidden=i>0&&(memory||affinity));$('dAmountRow').hidden=!$('dEffect').value;$('dComboFields').hidden=!$('dPartner').value;refreshAudioControl('dSound');if(readAudioControl('dSound'))$('definitionSoundSettings').open=true;const art=C.image($('image').value),preview=$('acquisitionPreview');preview.hidden=!art;$('removeAcquisitionImage').hidden=!art;$('centerAcquisitionImage').hidden=!art;if(art){if(preview.getAttribute('src')!==art)preview.src=art;const ratio=((innerWidth>=600?440:innerWidth)*.74-2)/(Math.min(260,innerHeight*.34)-2),h=Math.min(180,innerHeight*.22),w=Math.min((preview.parentElement.clientWidth||$('modalBody').clientWidth-24)-2,h*ratio);preview.style.width=(w+2)+'px';preview.style.height=(w/ratio+2)+'px';preview.style.objectPosition=C.imageOffset(Number($('imageX').value))+'% '+C.imageOffset(Number($('imageY').value))+'%';$('acquisitionSettings').open=true;}else preview.removeAttribute('src');};
 bindForm({type:'definition',id:d.id,game:store.active},commit,refresh);if(!existing&&!$('dName').value)setTimeout(()=>$('dName')?.focus(),0);bindAudioControl('dSound',()=>{rememberForm();commit(false);},{guard:()=>activeForm?.meta.id===d.id&&!!$('dSoundSrc')});
 const setArt=art=>{if(!activeForm||activeForm.meta.id!==d.id||!$('image'))return;$('image').value=art;$('imageX').value=50;$('imageY').value=50;refresh();rememberForm();commit(false);};
 bindAcquisitionPosition(refresh,commit);
 $('pickAcquisitionImage').onclick=()=>{imageCallback=setArt;$('imageFile').click();};$('removeAcquisitionImage').onclick=()=>setArt('');$('saveDef').onclick=()=>{if(commit(true))closeForm();};
}
function bindAcquisitionPosition(refresh,commit){
 const preview=$('acquisitionPreview');let drag=null;
 const savePosition=(x,y)=>{$('imageX').value=C.imageOffset(Math.round(x*10)/10);$('imageY').value=C.imageOffset(Math.round(y*10)/10);refresh();rememberForm();commit(false);};
 const geometry=()=>{const scale=Math.max(preview.clientWidth/preview.naturalWidth,preview.clientHeight/preview.naturalHeight);return {x:Math.max(0,preview.naturalWidth*scale-preview.clientWidth),y:Math.max(0,preview.naturalHeight*scale-preview.clientHeight)};};
 const move=(base,dx,dy)=>savePosition(base.overflow.x>.5?base.x-dx/base.overflow.x*100:base.x,base.overflow.y>.5?base.y-dy/base.overflow.y*100:base.y);
 preview.ondragstart=()=>false;
 preview.onpointerdown=e=>{if(!e.isPrimary||e.button!==0||!preview.naturalWidth)return;e.preventDefault();preview.focus({preventScroll:true});drag={id:e.pointerId,startX:e.clientX,startY:e.clientY,x:Number($('imageX').value),y:Number($('imageY').value),overflow:geometry()};preview.setPointerCapture(e.pointerId);preview.classList.add('dragging');};
 preview.onpointermove=e=>{if(!drag||drag.id!==e.pointerId)return;e.preventDefault();move(drag,e.clientX-drag.startX,e.clientY-drag.startY);};
 const end=e=>{if(!drag||drag.id!==e.pointerId)return;if(preview.hasPointerCapture(e.pointerId))preview.releasePointerCapture(e.pointerId);drag=null;preview.classList.remove('dragging');};
 preview.onpointerup=end;preview.onpointercancel=end;preview.onlostpointercapture=()=>{drag=null;preview.classList.remove('dragging');};
 preview.onkeydown=e=>{if(e.key==='Home'){e.preventDefault();savePosition(50,50);return;}const delta={ArrowLeft:[-12,0],ArrowRight:[12,0],ArrowUp:[0,-12],ArrowDown:[0,12]}[e.key];if(!delta||!preview.naturalWidth)return;e.preventDefault();const n=e.shiftKey?3:1;move({x:Number($('imageX').value),y:Number($('imageY').value),overflow:geometry()},delta[0]*n,delta[1]*n);};
 $('centerAcquisitionImage').onclick=()=>savePosition(50,50);
}
for(const [id,key,min]of[['initialMental','mental',1],['initialMoney','money',0]])$(id).onchange=()=>{const n=Number($(id).value);if(!Number.isInteger(n)||n<min||n>3){tell(min+'~3의 정수를 입력하세요.');return renderDefs();}project[key]=n;persist();};$('randomStart').onchange=()=>{project.randomStart=Number($('randomStart').value);persist();};$('addDef').onclick=()=>definitionForm();$('initialHp').onchange=()=>{const n=Number($('initialHp').value);if(!Number.isInteger(n)||n<1||n>project.maxHp){tell('시작 체력은 1~'+project.maxHp+' 사이로 입력하세요. 최대 체력은 '+project.maxHp+'입니다.');return renderDefs()}project.hp=n;persist()};$('maxHp').onchange=()=>{const n=Number($('maxHp').value);if(!Number.isInteger(n)||n<1||n>99){tell('1~99의 정수를 입력하세요.');return renderDefs()}project.maxHp=n;project.hp=Math.min(project.hp,n);persist();renderDefs()};
