 if(!parts.length)return;
 const acquired=(change.items||[]).filter(i=>i.delta>0).map(i=>run.p.definitions.find(d=>d.id===i.id)).filter(Boolean),gained=acquired.find(d=>C.image(d.image)),primary=acquired.find(d=>d.highlight)||acquired.find(d=>d.type==='ability')||acquired[0];
 const loss=run.dead||change.hp<0||change.mental<0||change.money<0||(change.items||[]).some(i=>i.delta<0)||people.some(x=>x.delta<0),harm=run.dead||change.hp<0||change.mental<0;
 const rewardTheme=primary?(primary.highlight?'important':primary.type):change.money>0?'money':'recovery',theme=run.dead?'death':harm?'loss':loss&&!primary?'loss':rewardTheme;
 const cue=run.dead?'death':harm&&primary?'mixed':harm?'loss':loss&&!primary?'loss':rewardTheme;
