 if(gained)showAcquisition(gained);
 noticeAnimations.push(...GameFeedback.present({theme},!!gained));
 // The small leading symbol occupies part of the same line. Recompute the
 // long-text travel after adding it, preserving the original 8-second bound.
 const text=$('statusText'),message=$('statusMessage'),overflow=Math.max(0,text.offsetLeft+text.scrollWidth-message.clientWidth+8);
 if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&overflow>0){
  for(const a of noticeAnimations.filter(a=>a.effect.target===text))a.cancel();
  const hold=Math.min(8000,Math.max(primary?.highlight?3400:2800,1700+overflow/50*1000));
  noticeAnimations.push(text.animate([{transform:'translateX(0)',offset:0},{transform:'translateX(0)',offset:.18},{transform:`translateX(-${overflow}px)`,offset:.85},{transform:`translateX(-${overflow}px)`,offset:1}],{duration:hold,fill:'forwards'}));clearTimeout(noticeTimer);noticeTimer=setTimeout(clearEffects,hold);
 }
 if(!endSceneSounds(run))GameFeedback.play(cue,!run.dead?primary?.sound:null);
