function showChecks(extra=''){
const issues=C.inspect(project);open('이야기 점검',`<p class="hint">연결·입력과 획득 항목의 사용처를 확인합니다. 보유 상태별 모든 경로를 증명하는 검사는 아니므로 조건 분기는 직접 테스트하세요.</p>${extra?`<p class="loss">${esc(extra)}</p>`:''}${issues.length?issues.map((i,n)=>`<button class="issue" data-issue="${n}"><b>${i.level==='error'?'수정 필요':'확인'} · ${esc(project.events.find(e=>e.id===i.event)?.title||'시작 설정')}</b><span>${esc(i.message)}</span></button>`).join(''):'<p>발견된 연결·입력 문제가 없습니다.</p>'}`);
$('modalBody').querySelectorAll('[data-issue]').forEach(b=>b.onclick=()=>{const issue=issues[Number(b.dataset.issue)];$('modal').close();if(issue.event){selected=issue.event;part=issue.choice?'choices':'content';page='story';}else page='inventory';render();const choice=issue.choice&&project.events.find(x=>x.id===issue.event)?.choices.find(c=>c.id===issue.choice);if(choice)choiceForm(choice);else $('editor')?.scrollTo?.({top:0});});
}
$('checkStory').onclick=()=>showChecks();$('testHere').onclick=()=>{try{C.validate(clone(project));if(C.inspect(project).some(i=>i.level==='error'))return showChecks();}catch(e){return showChecks(e.message);}startTest(selected);tell('이 사건부터 테스트합니다. 보유 상태에서 수량을 바꿀 수 있어요.');};
function deleteEvent(e,done){
if(project.events.length===1)return tell('사건은 하나 이상 있어야 합니다.');
const refs=[];for(const x of project.events)if(x.id!==e.id)for(const c of x.choices){if(c.next===e.id)refs.push({scene:x,c,out:c});if(c.branch?.next===e.id)refs.push({scene:x,c,out:c.branch});}
const remove=()=>{const at=project.events.findIndex(x=>x.id===e.id);project.events=project.events.filter(x=>x.id!==e.id);if(selected===e.id)selected=project.events[Math.max(0,at-1)].id;persist();renderEditor();tell('사건을 삭제했습니다. ↶ 되돌리기로 복구할 수 있어요.');done?.();};
if(!refs.length){if(confirm('「'+(e.title||'제목 없음')+'」 사건을 삭제할까요? ↶ 되돌리기로 복구할 수 있어요.'))remove();return;}
open('연결된 사건 삭제',`<p>「${esc(e.title)}」${josa(e.title||'사건','으로')} 연결된 결과가 ${refs.length}개 있어요. 대신 연결할 곳을 정한 뒤 삭제하세요.</p><p class="hint">${refs.slice(0,3).map(r=>esc(r.scene.title)+' → '+esc(r.c.text)).join('<br>')}${refs.length>3?'<br>외 '+(refs.length-3)+'개':''}</p><label>대신 연결할 곳<select id="replacement"><option value="">선택해 주세요</option><option value="sequence">사건 끝 · 다음 스토리</option>${rollOptions().replace(/🎲 랜덤 · /g,'사건 끝 · 🎲 ').replace('>랜덤 인카운터<','>사건 끝 · 랜덤 인카운터<')}<option value="end">이야기 끝 · 엔딩</option>${project.events.filter(x=>x.id!==e.id).map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join('')}</select></label><button id="confirmDelete" class="full danger" disabled>연결을 바꾸고 삭제</button>`);
$('closeModal').textContent='취소';$('replacement').onchange=()=>$('confirmDelete').disabled=!$('replacement').value;$('confirmDelete').onclick=()=>{for(const r of refs)r.out.next=$('replacement').value;$('modal').close();remove();};
}
$('undoTest').onclick=()=>{if(playing||!testPast.length)return;GameAudio.stopAll();run.restore(testPast.pop());clearEffects();renderTest();if($('stateSheet').open)renderStateSheet();};
$('editCurrent').onclick=()=>{GameAudio.stopAll();selected=run.current;part='content';$('stateSheet').close();page='story';render();};
$('adjustTest').onclick=()=>{
$('stateSheet').close();open('테스트 보유량 설정',`<p class="hint">현재 테스트에만 적용합니다. 이야기의 시작 설정은 바뀌지 않습니다.</p><div class="row"><label>체력<input id="tHp" type="number" min="1" max="${run.p.maxHp}" value="${Math.max(1,run.hp)}"></label><label>멘탈<input id="tMental" type="number" min="1" max="3" value="${Math.max(1,run.mental)}"></label><label>돈<input id="tMoney" type="number" min="0" max="3" value="${run.money}"></label></div>${run.p.definitions.map(d=>`<label>${esc(d.name)} ${d.type==='ability'?'레벨':'수량'}<input data-test-quantity="${d.id}" type="number" min="0" max="999" value="${run.bag[d.id]||0}"></label>`).join('')}<button id="applyTestState" class="full">테스트에 적용</button>`);
$('closeModal').textContent='취소';
$('applyTestState').onclick=()=>{const hp=Number($('tHp').value),mental=Number($('tMental').value),money=Number($('tMoney').value),bag=Object.fromEntries([...$('modalBody').querySelectorAll('[data-test-quantity]')].map(x=>[x.dataset.testQuantity,Number(x.value)]));if(!Number.isInteger(hp)||hp<1||hp>run.p.maxHp||!Number.isInteger(mental)||mental<1||mental>3||!Number.isInteger(money)||money<0||money>3||Object.entries(bag).some(([id,n])=>{const aff=run.p.definitions.find(d=>d.id===id)?.type==='affinity';return !Number.isInteger(n)||n<(aff?C.AFFINITY[0]:0)||n>(aff?C.AFFINITY[1]:999);}))return formError('수량과 생존 자원의 범위를 확인하세요.');testPast.push(run.snapshot());if(testPast.length>30)testPast.shift();Object.assign(run,{hp,mental,money,bag,lastChange:null,message:'테스트 보유량을 적용했습니다.'});if(run.dead){run.dead=false;run.ended=false;run.deathReason='';}$('modal').close();renderTest();};
};

function quickTest(){
 if(playing||!run)return;if(run.pendingReward)return tell('보상을 고른 뒤 조건을 비교하세요.');const e=run.p.events.find(x=>x.id===run.current);if(!e||run.ended)return tell('진행 중인 장면에서 사용할 수 있어요.');
 const requirements=new Map();for(const c of e.choices){for(const {id,count:n}of[...C.needsOf(c),...C.whensOf(c.branch),...C.losesOf(c),...C.losesOf(c.branch)])if(id)requirements.set(id,Math.max(requirements.get(id)||0,n));}
 for(const text of [e.text,e.speaker,...e.choices.map(c=>c.text)]){const info=GameVariations.inspect(text,n=>run.textValue(n,e)!==undefined);for(const [n,need]of Object.entries(info.needs)){const d=run.p.definitions.find(d=>d.name===n);if(d)requirements.set(d.id,Math.max(requirements.get(d.id)||0,need));}}
 const all=[...requirements].filter(([id])=>!C.resources[id]);
 open('조건 비교',`<p class="hint">현재 테스트의 보유 상태만 바꿉니다. 사건과 시작 설정은 그대로 유지됩니다.</p><div id="compareConditions"></div><p id="compareLine" class="compareLine"></p><div id="compareResults"></div><button id="compareAllState" class="full quiet">체력·멘탈·돈 / 전체 보유량 설정</button>`);
 function draw(){
 $('compareConditions').innerHTML=all.length?all.map(([id,n])=>`<div class="compareCondition"><b>${esc(run.name(id))}</b><button data-compare-id="${id}" data-value="0" class="${run.value(id)<n?'active':''}">미보유</button><button data-compare-id="${id}" data-value="${n}" class="${run.value(id)>=n?'active':''}">보유</button></div>`).join(''):'<p class="hint">이 사건에는 능력·아이템 조건이 없습니다.</p>';
 $('compareConditions').querySelectorAll('[data-compare-id]').forEach(b=>b.onclick=()=>{testPast.push(run.snapshot());if(testPast.length>30)testPast.shift();run.bag[b.dataset.compareId]=Number(b.dataset.value);run.lastChange=null;clearEffects();renderTest();draw();});
 $('compareLine').textContent=run.say(e.text,e);$('compareResults').innerHTML=e.choices.map(c=>{const out=run.resolved(c),effects=[['hp','체력'],['mental','멘탈'],['money','돈']].filter(([key])=>out[key]).map(([key,label])=>label+' '+(out[key]>0?'+':'')+out[key]);if(c.reward)effects.push('랜덤 보상 '+c.reward.pool.length+'종 중 선택');for(const n of out.effectNotes)effects.push(n.name+' 적용');for(const x of C.gainsOf(out))effects.push(run.name(x.id)+' +'+x.count);for(const x of C.losesOf(out))effects.push(run.name(x.id)+' -'+x.count);return `<div class="compareResult"><b>${esc(run.say(c.text,e))}</b><small>${run.blocked(c)?(c.hideLocked?'숨김':'선택 불가'):run.outcome(c)===c.branch?'보유 조건 결과':'기본 결과'} · ${esc(effects.join(' · ')||'변화 없음')}<br>→ ${esc(nextName(out.next))}</small></div>`;}).join('');
 }
 $('compareAllState').onclick=()=>{$('modal').close();$('adjustTest').click();};draw();
}

$('quickTest').onclick=quickTest;
