window.addEventListener('game-audio-error',e=>tell(e.detail));document.addEventListener('visibilitychange',()=>{if(document.hidden){GameAudio.suspend();clearEffects();finishDialogue();saveAll();}else GameAudio.resume();});window.flushPersist=saveAll;window.appBack=()=>{if(window.SceneHelpers?.closeSymbols())return 'HANDLED';if(window.ArtPicker?.isOpen()){ArtPicker.close();return 'HANDLED';}if(window.StoryMap?.isOpen()&&!$('modal').open){leaveStoryMap(true);return 'HANDLED';}if(window.closeStagePreview&&closeStagePreview())return 'HANDLED';if($('cropSheet').open){closeCrop();return 'HANDLED'}if($('creditsSheet').open){GameTitle.close();return 'HANDLED'}if($('historySheet').open){closeHistory();return 'HANDLED'}if(artViewing){restoreDialogue();return 'HANDLED'}if($('stateSheet').open){closeStateSheet();return 'HANDLED'}if($('modal').open){closeForm();return 'HANDLED'}if(playing){leavePlay();return 'HANDLED'}if(!standalone&&backPlace())return 'HANDLED';if(page==='gameList'){showHome();return 'HANDLED'}if(page==='test'||page==='inventory'){switchPage('story');return 'HANDLED'}if(page==='story'){showHome();return 'HANDLED'}return 'EXIT'};
