async function deleteGame(){if(apkExporting||creatorBusy)return tell('파일 저장이 끝난 뒤 삭제하세요.');if(!confirm('「'+(project.title||'제목 없는 게임')+'」'+josa(project.title||'게임','과')+' 진행을 삭제할까요? 7일 안에 복구할 수 있습니다.'))return;if(!await flushEditor())return;const before=store.games.slice(),trash=store.trash?.slice(),forms={...store.formDrafts},active=store.active;GameManagement.remove(store,active);try{await GameVault.write(store);}catch(e){store.games=before;store.trash=trash;store.formDrafts=forms;store.active=active;return tell('삭제 내용을 저장하지 못했습니다.');}activeForm=null;$('modal').close();const g=store.games.find(g=>g.id===store.active);project=g?clone(g.draft):null;history=project?new EditorHistory(project):null;selected=project?.events[0]?.id||'';dirty=false;run=null;showList('editor');tell('삭제했습니다. 복구 버튼에서 7일 안에 되돌릴 수 있습니다.');}
function showDeletedGames(){GameManagement.expire(store);open('최근 삭제한 게임',`<p class="hint">삭제한 날부터 7일 동안 그림·소리와 진행까지 복구합니다.</p>${store.trash?.length?store.trash.map(t=>`<button class="eventResult" data-restore-game="${t.game.id}"><span>${esc(t.game.draft.title)}</span><small>복구 · ${Math.max(1,Math.ceil((7*86400000-(Date.now()-t.deletedAt))/86400000))}일 남음</small></button>`).join(''):'<p>복구할 게임이 없습니다.</p>'}`);$('modalBody').querySelectorAll('[data-restore-game]').forEach(b=>b.onclick=async()=>{const before=store.games.slice(),trash=store.trash.slice(),forms={...store.formDrafts},active=store.active;try{const g=GameManagement.restore(store,b.dataset.restoreGame);await GameVault.write(store);$('modal').close();await openGame(g.id);tell('게임과 진행을 복구했습니다.');}catch(e){store.games=before;store.trash=trash;store.formDrafts=forms;store.active=active;tell(e.message);}});GameVault.write(store).then(()=>GameVault.prune()).catch(()=>{});}
function finishSettings(){const owner=store.active;let image=project.finish?.death?.image||'';open('일반 사망 연출',`<p class="hint">체력·멘탈이 0이 되어 죽을 때 나옵니다. 비우면 원래 장면과 기본 문구를 씁니다. 특별한 죽음은 사건의 진행 방식을 ‘사망 장면’으로 만드세요.</p><label>사망 문구<textarea id="deathText" rows="3" maxlength="1000">${esc(project.finish?.deathText||'')}</textarea></label><img id="deathPreview" class="smallMediaPreview" hidden><div class="row"><button id="deathPick">그림 선택</button><button id="deathClear" class="quiet">그림 제거</button></div><button id="deathDone" class="full">완료</button>`);const preview=()=>{const img=$('deathPreview');img.hidden=!image;if(image)img.src=image;};const commit=()=>{project.finish={deathText:$('deathText').value,death:image?{image}: {}};persist();return true;};bindForm({type:'finish',id:'finish'},commit,preview);$('deathPick').onclick=()=>{imageCallback=v=>{if(activeForm?.meta.type!=='finish'||store.active!==owner)return;image=v;preview();commit();};$('imageFile').click();};$('deathClear').onclick=()=>{image='';preview();commit();};$('deathDone').onclick=closeForm;}

let cropCommit=null;function closeCrop(){if(!$('cropSheet').open)return;cropCommit?.();cropCommit=null;$('cropSheet').close();}
function openCrop(kind,refresh){if(apkExporting)return;const meta=project.landing||{},scene=project.events[0],src=(kind==='icon'?meta.icon?.image:'')||meta.image||C.art(project,scene,'top').image||C.art(project,scene,'bottom').image;if(!src)return tell('먼저 메인 그림을 선택하세요.');const frame=$('cropFrame');frame.className=kind==='cover'?'titleFrame':'iconCropFrame';frame.replaceChildren();GameThemes.apply(frame,project.theme);let target=frame;if(kind==='cover'){GameTitle.preview(frame,project,meta);frame.removeAttribute('data-title-preview');target=frame.querySelector('.titleCover');target.querySelector('img')?.removeAttribute('id');frame.querySelector('.titleCard').classList.add('cropTitleGuide');}else{target=document.createElement('div');target.className='iconCropTarget';frame.append(target);const guide=document.createElement('small');guide.textContent='밝은 칸 안이 아이콘에 보입니다. 기기에 따라 점선 동그라미처럼 잘립니다.';frame.append(guide);}let changed=false;let value=ImageCompose.setting(meta[kind]);ImageCompose.paint(target,src,value);const gestures=ImageCompose.gestures(target,value,v=>{value=v;changed=true;});target.tabIndex=0;target.setAttribute('aria-label','그림 표시 위치 · 방향키로 이동, +와 -로 확대');$('cropSheet').showModal();ImageCompose.paint(target,src,value);cropCommit=()=>{if(changed){project.landing||={};project.landing[kind]={...project.landing[kind],...value};persist();}refresh();};$('cropReset').onclick=()=>gestures.reset();$('cropDone').onclick=closeCrop;}
$('cropSheet').addEventListener('cancel',e=>{e.preventDefault();closeCrop();});

let creatorBusy=false,fileExportCallback=null,latestApkCallback=null;
function creatorMessage(text,error=false){const box=$('creatorMessage');if(box){box.textContent=text;box.classList.toggle('loss',error);if(error&&/암호/.test(text))$('creatorPassword')?.focus();}else tell(text);}
function creatorLock(busy){creatorBusy=busy;if($('creatorAction')){$('creatorAction').disabled=busy;$('modalBody').querySelectorAll('input,button').forEach(x=>x.disabled=busy);}$('closeModal').disabled=busy;}
function creatorBackupForm(first=false){if(creatorBusy||apkExporting)return;if(!window.Android?.backupSigning)return tell('제작자 배포 백업은 Android 앱에서 사용할 수 있습니다.');open(first?'첫 배포 · 제작자 백업':'제작자 백업',`<p class="hint">${first?'처음 배포하기 전에 백업을 한 번 저장하세요. 이후 APK는 암호를 다시 묻지 않고 만듭니다.':'현재 게임과 진행, 배포 서명을 한 파일에 보관합니다.'} 복원할 때 이 파일과 암호가 필요합니다.</p><label>백업 암호<input id="creatorPassword" type="password" minlength="4" maxlength="200" autocomplete="new-password" placeholder="4자 이상"></label><label>암호 확인<input id="creatorConfirm" type="password" maxlength="200" autocomplete="new-password"></label><p id="creatorMessage" class="hint" role="status">이 파일은 제작자 보관용입니다. 플레이어에게는 게임 APK를 보내세요.</p><button id="creatorAction" class="full">${first?'백업 저장 후 APK 만들기':'제작자 백업 저장'}</button>`);const target=store.active;$('creatorAction').onclick=async()=>{const password=$('creatorPassword').value;if(password!==$('creatorConfirm').value)return formError('두 암호가 다릅니다.','creatorConfirm');if(password.length<4)return formError('암호를 4자 이상 입력하세요.','creatorPassword');creatorLock(true);let waiting=false;try{if(!await flushEditor())throw Error('편집 내용을 저장하지 못했습니다.');const signing=JSON.parse(Android.backupSigning(target));if(signing.error)throw Error(signing.error);const game=clone(store.games.find(g=>g.id===target));const payload={format:'event-creator-payload',version:1,gameData:GameVault.encode({format:'event-vault',version:1,active:game.id,games:[game],formDrafts:Object.fromEntries(Object.entries(store.formDrafts||{}).filter(([k])=>k.startsWith(game.id+':')))}),signing};creatorMessage(signing.mode==='legacy'?'기존 배포 서명은 현재 휴대폰에서만 사용할 수 있습니다. 게임·진행과 배포 정보는 암호화해 저장합니다.':'게임과 배포 정보를 암호화하는 중…');const data=await CreatorBackup.encrypt(payload,password);fileExportCallback=async(ok,message)=>{creatorLock(false);if(ok){if($('creatorPassword'))$('creatorPassword').value='';if($('creatorConfirm'))$('creatorConfirm').value='';if(signing.mode==='portable'&&!Android.markCreatorBackup(target))return creatorMessage('백업은 저장했지만 완료 표시를 저장하지 못했습니다. 다시 백업하세요.');creatorMessage('제작자 백업을 저장했습니다. 파일과 암호를 보관하세요.');if(first&&store.active===target){$('modal').close();apkExportForm();await exportGameApk();}}else creatorMessage(message);};Android.exportFile(data,(game.draft.title||'게임').replace(/[\\/:*?"<>|]/g,'_')+'-제작자백업.json','application/json');waiting=true;creatorMessage('백업 파일을 저장할 위치를 선택하세요.');}catch(e){creatorMessage(e.message,true);}finally{if(!waiting)creatorLock(false);}};}
window.onFileExportResult=(ok,message)=>{const callback=fileExportCallback;fileExportCallback=null;if(callback)callback(ok,message);};
function creatorRestoreForm(){if(creatorBusy||apkExporting)return;open('제작자 백업 복원',`<p class="hint">게임·그림·음악·진행을 함께 복원합니다. 새 배포 방식의 백업은 다른 휴대폰에서도 같은 게임의 업데이트 APK를 만들 수 있습니다.</p><button id="creatorPick" class="full">제작자 백업 파일 선택</button><small id="creatorFilename" class="audioFileName"></small><label>백업 암호<input id="creatorPassword" type="password" maxlength="200" autocomplete="current-password"></label><details id="latestApkDetails" hidden><summary>오래된 백업의 배포 버전 확인 · 선택</summary><p class="hint">백업 후 APK를 더 배포했다면 최근 APK를 선택하세요. 앱 ID와 서명을 확인하고 더 높은 버전으로 내보냅니다.</p><button id="latestApkPick" class="full quiet">최근 배포 APK 선택</button><small id="latestApkMessage"></small></details><p id="creatorMessage" class="hint" role="status">백업 파일을 고르고 암호를 입력하세요.</p><button id="creatorAction" class="full" disabled>복원</button>`);let raw='',prepared=null,latest=0;const prepare=async()=>{if(prepared)return prepared;if(!raw)throw Error('제작자 백업 파일을 선택하세요.');const p=await CreatorBackup.decrypt(raw,$('creatorPassword').value);if(p.format!=='event-creator-payload'||p.version!==1||!p.signing)throw Error('제작자 백업 내용 형식');const v=GameVault.decode(p.gameData);if(v.games.length!==1||v.trash?.length)throw Error('게임 백업 구성');const game=v.games[0];if(!['portable','legacy'].includes(p.signing.mode)||!Number.isInteger(p.signing.version)||p.signing.version<0)throw Error('배포 백업 형식');prepared={game,signing:p.signing,formDrafts:Object.fromEntries(Object.entries(v.formDrafts||{}).filter(([k])=>k.startsWith(game.id+':')))};$('latestApkDetails').hidden=!window.Android?.chooseLatestApk;return prepared;};$('creatorPassword').oninput=()=>{prepared=null;latest=0;};$('creatorPick').onclick=()=>$('creatorFile').click();$('creatorFile').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>155000000)return creatorMessage('백업 파일 크기 제한');raw=await f.text();prepared=null;latest=0;$('creatorFilename').textContent=f.name;$('creatorAction').disabled=false;$('latestApkDetails').hidden=!window.Android?.chooseLatestApk;};$('latestApkPick').onclick=async()=>{creatorLock(true);try{const p=await prepare();latestApkCallback=(ok,version,message)=>{creatorLock(false);if(ok)latest=Math.max(latest,version);$('latestApkMessage').textContent=message;};if(!Android.chooseLatestApk(JSON.stringify({package:p.signing.package,fingerprint:p.signing.fingerprint})))throw Error('APK 선택기를 열지 못했습니다.');}catch(e){creatorLock(false);creatorMessage(e.message,true);}};$('creatorAction').onclick=async()=>{creatorLock(true);try{const {game,signing,formDrafts}=await prepare();if(!window.Android?.restoreSigning)throw Error('배포 서명 복원은 Android 앱에서 사용할 수 있습니다.');if(store.games.some(g=>g.id===game.id)&&!confirm('같은 게임이 있습니다. 백업 시점의 내용과 진행으로 복원할까요? 지금 내용은 「복원 전」 사본으로 최근 삭제한 게임에 7일간 보관됩니다.'))return;if(!await flushEditor())throw Error('현재 편집 내용을 저장하지 못했습니다.');const result=JSON.parse(Android.restoreSigning(game.id,JSON.stringify(signing),latest));if(!result.ok)throw Error(result.error||'배포 정보 복원 실패');const before=store.games.slice(),trash=store.trash?.slice(),forms={...store.formDrafts},active=store.active;const current=store.games.find(g=>g.id===game.id);store.games=store.games.filter(g=>g.id!==game.id);if(store.games.length>=100)throw Error('게임은 최대 100개까지 보관할 수 있습니다.');store.trash=(store.trash||[]).filter(t=>t.game.id!==game.id);if(current){const copy=clone(current);copy.id=C.uid();copy.draft.title=(copy.draft.title||'제목 없는 게임')+' (복원 전)';store.trash.push({game:copy,deletedAt:Date.now(),formDrafts:{}});}store.games.push(game);store.formDrafts={...Object.fromEntries(Object.entries(store.formDrafts||{}).filter(([k])=>!k.startsWith(game.id+':'))),...formDrafts};store.active=game.id;try{await GameVault.write(store);}catch(e){store.games=before;store.trash=trash;store.formDrafts=forms;store.active=active;throw e;}if(signing.mode==='portable')Android.markCreatorBackup(game.id);$('creatorPassword').value='';creatorLock(false);$('modal').close();await openGame(game.id);tell(signing.mode==='legacy'?'복원했습니다. 기존 서명은 원래 휴대폰이 필요합니다.':'게임·진행·배포 정보를 복원했습니다.');}catch(e){creatorMessage(e.message,true);}finally{creatorLock(false);}};}
window.onLatestApkResult=(ok,version,message)=>{const callback=latestApkCallback;latestApkCallback=null;callback?.(ok,version,message);};
// Editor self-update (Android app only): a status line on the home screen.
let appUpdateTold='';
function renderAppUpdate(s){const box=$('appUpdate');if(!box||!s||!s.current)return;box.hidden=false;$('appUpdateAuto').checked=!!s.enabled;let text='버전 '+s.current,action='';
 if(s.installing)text+=' · 업데이트 설치 중…';
 else if(s.ready){text+=' · 새 버전 '+s.readyName+' 준비됨';if(!s.canInstall){action='설치 허용하기';text+='. 설정에서 이 앱의 \'알 수 없는 앱 설치\'를 한 번 허용해 주세요.';}else{action='지금 업데이트';if(s.silent&&s.enabled)text+='. 앱을 나가 있으면 자동으로 설치돼요.';else text+='. 처음 한 번은 설치 확인을 눌러 주세요.';}}
 else if(s.checking)text+=' · 새 버전 확인 중…';
 else if(s.error)text+=' · '+s.error;
 else if(s.lastCheck)text+=' · 최신 버전';
 $('appUpdateText').textContent=text;const b=$('appUpdateAction');b.hidden=!action;b.textContent=action;b.onclick=()=>{if(!s.canInstall)Android.openInstallSettings();else Android.installUpdate();};$('appUpdateCheck').disabled=!!s.checking||!!s.installing;
 if(s.ready&&appUpdateTold!==s.readyName){appUpdateTold=s.readyName;tell('새 버전 '+s.readyName+josa(s.readyName,'을')+' 받아 두었어요. 첫 화면에서 확인하세요.');}}
window.onAppUpdate=renderAppUpdate;
if(window.Android?.updateStatus&&!standalone){try{renderAppUpdate(JSON.parse(Android.updateStatus()));}catch(e){}$('appUpdateAuto').onchange=()=>Android.setAutoUpdate($('appUpdateAuto').checked);$('appUpdateCheck').onclick=()=>Android.checkUpdate();}

// Back goes to the screen before, wherever it is: every distinct screen (page, game, scene, tab, 구조도) is remembered in order.
let places=[],placing=false;
function place(){const edit=['story','inventory','test'].includes(page);return {page,listMode:page==='gameList'?listMode:'',game:edit?store.active:'',selected:edit?selected:'',part:page==='story'?part:'',map:!!window.StoryMap?.isOpen()};}
const samePlace=(a,b)=>!!a&&!!b&&JSON.stringify(a)===JSON.stringify(b);
function notePlace(){if(placing||standalone||playing)return;const now=place();if(samePlace(places[places.length-1],now))return;places.push(now);if(places.length>60)places.shift();}
function syncPlace(){if(standalone||playing)return;const now=place();if(places.length)places[places.length-1]=now;else places.push(now);}
function backPlace(){if(samePlace(places[places.length-1],place()))places.pop();
 while(places.length){const to=places[places.length-1];if(to.game&&!store.games.some(g=>g.id===to.game)){places.pop();continue;}restorePlace(to);return true;}return false;}
async function restorePlace(to){placing=true;try{
 if(to.page==='home')await showHome();
 else if(to.page==='gameList')showList(to.listMode);
 else{if(to.game&&store.active!==to.game)await openGame(to.game);
  if(to.selected&&project.events.some(e=>e.id===to.selected))selected=to.selected;if(to.part)part=to.part;
  if(to.page==='test')switchPage('test');else{page=to.page;render();}
  if(to.map)openStoryMap('');}
}finally{placing=false;syncPlace();}}
{const baseRender=render,baseEditor=renderEditor;render=function(...a){const out=baseRender.apply(this,a);notePlace();return out;};renderEditor=function(...a){const out=baseEditor.apply(this,a);notePlace();return out;};}
notePlace();
